// Dynamic Motion Graphic Animation (AI Generated): dm-elem-s0
{
  const subTl = gsap.timeline();
  const el = document.getElementById("dm-elem-s0") || document.querySelector("#dm-elem-s0") || document.querySelector(".dynamic-motion-visual");
  if (el) {
    gsap.set(el, { opacity: 0, pointerEvents: "none" });
    try {
      (function(tl, el) {
        tl.fromTo('#dm-elem-s0', { opacity: 0, scale: 0.7 }, { opacity: 1, scale: 1, duration: 0.8 }, 0); tl.to('#dm-elem-s0 .outer-ring', { rotation: 360, transformOrigin: 'center center', duration: 3.5, ease: 'linear', repeat: 1 }, 0.2); tl.to('#dm-elem-s0 .middle-ring', { rotation: -360, transformOrigin: 'center center', duration: 3.5, ease: 'linear', repeat: 1 }, 0.2); tl.to('#dm-elem-s0 .inner-ring', { rotation: 720, transformOrigin: 'center center', duration: 3.5, ease: 'linear', repeat: 1 }, 0.2); tl.to('#dm-elem-s0 .central-bindu', { scale: 1.2, opacity: 0.8, yoyo: true, repeat: 6, duration: 0.5, ease: 'power1.inOut' }, 0.5); tl.to('#dm-elem-s0', { opacity: 0, scale: 0.7, duration: 0.8 }, '+=3.2');
      })(subTl, el);
    } catch(err) {
      console.warn("Error running custom motion JS:", err);
    }

    // Normalize start time so subTl always starts at 0 internally
    const children = subTl.getChildren();
    if (children && children.length > 0) {
      const minStart = Math.min(...children.map((c) => c.startTime()));
      if (minStart > 0 && Number.isFinite(minStart)) {
        subTl.shiftChildren(-minStart, true);
      }
    }

    const effDur = Math.max(2.0, subTl.duration() || 4);
    subTl.to(el, { opacity: 0, duration: 0.6, ease: "power2.in" }, Math.max(0.5, effDur - 0.6));
    tl.add(subTl, 1);
  }
}

